using System.Diagnostics;
using System.Security.Cryptography;
using System.Text.Json;
using FreshFoundation;
internal static class WorkspaceChecks
{
    internal static int Run()
    {
        var cases=new List<object>();int failed=0;var timings=new Dictionary<string,double>();string root=Path.Combine(Directory.GetCurrentDirectory(),"synthetic-run-r5-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
        void Assert(bool value){if(!value)throw new Exception("Functional assertion failed");}
        void Test(string name,Action test){try{test();cases.Add(new{name,status="PASS"});}catch(Exception e){failed++;cases.Add(new{name,status="FAIL",error=e.Message});}}
        string slot=Path.Combine(root,"data001Slot.bin");File.WriteAllBytes(slot,WorkspaceSyntheticSamples.Slot(missingMasterRank:true));File.WriteAllBytes(Path.Combine(root,"data002Slot.bin"),[1,2,3]);File.WriteAllBytes(Path.Combine(root,"data00-1.bin"),WorkspaceSyntheticSamples.SystemFile());
        var workspace=new EditorWorkspace();workspace.Open(slot);var domain=new DomainEditor(workspace);string before=workspace.Document!.Digest;
        Test("four candidate discovery keeps good slot despite unsupported and missing slots",()=>{var rows=SlotDiscovery.Discover(root);Assert(rows.Count==4&&rows[0].Status==SlotStatus.Recognized&&rows[1].Status==SlotStatus.Unsupported&&rows[2].Status==SlotStatus.Empty&&rows[3].Label=="System");});
        Test("root child parent context and paged global ID text search",()=>{var roots=workspace.Browse();Assert(roots.Total==4);int rootEvent=roots.Rows[1].EventIndex;var children=workspace.Browse(rootEvent);Assert(children.Rows.Count==1&&children.Rows[0].ParentIndex==rootEvent);Assert(workspace.Browse(query:"_not_a_name_").Total==0);Assert(workspace.Browse(query:"Synthetic Hunter").Total==1);Assert(workspace.Browse(query:"0x00000200").Total==1&&workspace.Browse(query:"0x00000200").Rows[0].OpaqueIdentifier=="0x00000200");});
        Test("complete domain paths ignore unrelated Data1 root; independent ranks",()=>{var c=domain.Character();Assert(c.Name=="Synthetic Hunter 1"&&c.Money==2000&&c.Points==5000&&c.HunterRank==120&&c.MasterRank is null);Assert(domain.Inventory().Count==3&&domain.Inventory()[0].Quantity==9999);});
        Test("ambiguous complete money path disables only money",()=>{string p=Path.Combine(root,"ambiguous.bin");File.WriteAllBytes(p,WorkspaceSyntheticSamples.Slot(duplicateMoneyPath:true));var w=new EditorWorkspace();w.Open(p);var d=new DomainEditor(w);Assert(!d.CanEditMoney&&d.CanEditPoints&&d.Inventory().Count==3);});
        Test("money points item quantity add known ID delete refresh staging",()=>{workspace=new EditorWorkspace();workspace.Open(slot);domain=new DomainEditor(workspace);void Reject(Action action){int count=workspace.StagedCount;bool rejected=false;try{action();}catch(ArgumentOutOfRangeException){rejected=true;}catch(InvalidOperationException){rejected=true;}Assert(rejected&&workspace.StagedCount==count);}Reject(()=>domain.SetMoney(2001));Reject(()=>domain.SetPoints(5001));Reject(()=>domain.SetItemQuantity(0,10000));Reject(()=>domain.AddKnownItem(domain.KnownItemIds[0],1));domain.SetMoney(1500);domain.SetPoints(4000);domain.SetItemQuantity(0,7000);int added=domain.AddKnownItem(domain.KnownItemIds[0],2222);Reject(()=>domain.SetItemQuantity(0,8000));domain.DeleteItem(2);Assert(added==1&&domain.Inventory()[0].Quantity==7000&&domain.Inventory()[1].Quantity==2222&&domain.Inventory()[2].Id==DomainEditor.EmptyItemId&&domain.Inventory()[2].Quantity==0&&domain.Character().Money==1500);});
        Test("equipment type filters decoration read and paired talisman edit",()=>{workspace=new EditorWorkspace();workspace.Open(slot);domain=new DomainEditor(workspace);Assert(domain.Equipment(3).Count==2&&domain.DecorationIds(3).SequenceEqual(new uint[]{11,12,0}));var choice=domain.KnownSkillPairs.Single(p=>p.Id==5&&p.Level==7);domain.SetTalismanPair(3,0,choice);Assert(domain.Talisman(3).Pairs[0]==choice);try{domain.SetTalismanPair(1,0,choice);throw new Exception("Accepted weapon as talisman");}catch(InvalidOperationException){}Assert(domain.Equipment(1).Count==1);});
        Test("staged domain export reload preserves other bytes",()=>{workspace=new EditorWorkspace();workspace.Open(slot);domain=new DomainEditor(workspace);domain.SetMoney(1500);domain.SetPoints(4000);domain.SetItemQuantity(0,7000);domain.AddKnownItem(domain.KnownItemIds[0],2222);domain.DeleteItem(2);domain.SetTalismanPair(3,0,new SkillPair(5,7));var requests=workspace.Document!.Structure.Events.Select((e,i)=>(e,i)).Where(p=>p.e.DataCoordinate!=null).Where(p=>!workspace.PrimitiveBytes(p.i)!.SequenceEqual(workspace.PrimitiveBytes(p.i,true)!)).ToArray();var receipt=workspace.Export(Path.Combine(root,"edited.bin"),root);var reloaded=new EditorWorkspace();reloaded.Open(receipt.OutputPath);var d=new DomainEditor(reloaded);Assert(d.Character().Money==1500&&d.Character().Points==4000&&d.Inventory()[1].Quantity==2222&&d.Talisman(3).Pairs[0]==new SkillPair(5,7));var expected=workspace.Document.Structure.CopyPayload();foreach(var p in requests)workspace.PrimitiveBytes(p.i)!.CopyTo(expected,p.e.DataCoordinate!.Value-12);Assert(expected.SequenceEqual(reloaded.Document!.Structure.CopyPayload())&&workspace.Document.Digest==before);});
        Test("raw stage undo and clear operate without reparsing",()=>{workspace=new EditorWorkspace();workspace.Open(slot);new DomainEditor(workspace).SetMoney(1500);workspace.Clear();Assert(workspace.StagedCount==0);workspace.Undo();Assert(workspace.StagedCount>0);workspace.Clear();int index=workspace.Document!.Structure.Events.ToList().FindIndex(e=>e.DataCoordinate!=null);var raw=workspace.PrimitiveBytes(index)!;raw[0]^=1;workspace.Apply(index,raw);Assert(workspace.StagedCount==1);workspace.Undo();Assert(workspace.StagedCount==0&&workspace.Document.Digest==before);});
        Test("directory money mirror global undo clear and directory export",()=>{var group=new DirectoryEditor();group.OpenDirectory(root);group.OpenSlot(slot);Assert(group.System is not null);group.SetMoney(1500);Assert(group.Slot.StagedCount==1&&group.System!.StagedCount==1);group.Undo();Assert(group.StagedCount==0);group.SetMoney(1200);group.Clear();Assert(group.StagedCount==0);group.Undo();Assert(group.Slot.StagedCount==1&&group.System!.StagedCount==1);var results=group.ExportCopies(Path.Combine(root,"directory-copies"));Assert(results.Count==4&&results.Count(r=>r.Receipt is not null)==2&&results.Count(r=>r.Error is not null)==2);var system=Document.Inspect(File.ReadAllBytes(results.Single(r=>r.Label=="System").OutputPath!));Assert(system.Digest!=Document.Inspect(WorkspaceSyntheticSamples.SystemFile()).Digest);});
        Test("directory export makes complete four-file bundle preserving other slots",()=>{string folder=Path.Combine(root,"complete-input");Directory.CreateDirectory(folder);for(int i=1;i<=3;i++)File.WriteAllBytes(Path.Combine(folder,$"data00{i}Slot.bin"),WorkspaceSyntheticSamples.Slot(i));File.WriteAllBytes(Path.Combine(folder,"data00-1.bin"),WorkspaceSyntheticSamples.SystemFile());var group=new DirectoryEditor();group.OpenDirectory(folder);group.OpenSlot(Path.Combine(folder,"data002Slot.bin"));group.SetMoney(1700);var result=group.ExportCopies(Path.Combine(root,"complete-output"));Assert(result.Count==4&&result.All(r=>r.Receipt is not null));foreach(int i in new[]{1,3})Assert(File.ReadAllBytes(Path.Combine(folder,$"data00{i}Slot.bin")).SequenceEqual(File.ReadAllBytes(result.Single(r=>r.Label==$"Slot {i}").OutputPath!)));});
        Test("folder context switch clears old slot stages and explicit outside file exports itself",()=>{var group=new DirectoryEditor();group.OpenDirectory(root);group.OpenSlot(slot);group.SetMoney(1600);string other=Path.Combine(root,"other-folder");Directory.CreateDirectory(other);group.OpenDirectory(other);Assert(group.Domain is null&&group.Slot.Document is null&&group.StagedCount==0&&group.System is null);group.OpenSlot(slot);group.SetMoney(1400);var result=group.ExportCopies(Path.Combine(root,"outside-context-output"));Assert(result.Count==1&&result[0].Receipt is not null&&result[0].Label=="Selected file");});
        Test("500k event browsing search and paging remain bounded",()=>{var b=new SyntheticR2();b.Root(1,1,()=>b.Field(2,-1,()=>b.Array(1,1,500000,0,()=>b.Bytes.AddRange(new byte[500000]))));string p=Path.Combine(root,"large.bin");File.WriteAllBytes(p,b.File(true));var w=new EditorWorkspace();var clock=Stopwatch.StartNew();w.Open(p);timings["500k_open_ms"]=clock.Elapsed.TotalMilliseconds;clock.Restart();var page=w.Browse(parent:1,page:2499,pageSize:200);timings["500k_last_page_ms"]=clock.Elapsed.TotalMilliseconds;Assert(page.Rows.Count==200&&page.Total==500000);clock.Restart();Assert(w.Browse(query:"not-present").Total==0);timings["500k_search_ms"]=clock.Elapsed.TotalMilliseconds;Assert(timings["500k_last_page_ms"]<5000&&timings["500k_search_ms"]<10000);});
        File.WriteAllText("test-results-r9-workspace-regression.json",JsonSerializer.Serialize(new{executedAtUtc=DateTimeOffset.UtcNow,scope="Current R9 execution of R5 cases updated for conservative policy; historical R5 report retained. Focused synthetic workspace and domain functional checks, no repeated export-safety batch",cases,failed,timings,sourceHashes=Directory.GetFiles(Directory.GetCurrentDirectory(),"*.cs").Select(p=>new{file=Path.GetFileName(p),sha256=Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(p)))}).ToArray()},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine($"R5 functional cases={cases.Count}; failures={failed}");return failed==0?0:1;
    }
}
